CREATE OR REPLACE FUNCTION electronicclub.ec_table(p_collection text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
BEGIN
 IF p_collection NOT IN ('forum_boards','forum_posts','forum_comments','forum_likes','forum_favorites','forum_reports','forum_user_restrictions','forum_notifications','forum_images','events','event_managers','registrations','checkins','articles','popup_announcements','popup_state','users','roles','permissions','credentials','sessions','student_ids','audit_logs','import_jobs','login_limits','system','privacy_jobs') THEN RAISE EXCEPTION 'INVALID_COLLECTION'; END IF;
 RETURN format('electronicclub.%I',p_collection);
END $$;
CREATE OR REPLACE FUNCTION public.ec_forum_list(p_collection text,p_filter jsonb,p_offset integer,p_limit integer) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
PERFORM electronicclub.ec_assert_backend_role();
IF jsonb_typeof(p_filter)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_filter) k WHERE k NOT IN ('_createdBefore','_beforeFloor','status','boardId','postId','authorUid','recipientUid','reporterUid','ownerUid','uid','read','_search','_sort','_public','_favoriteUid','_featured','_notDeleted','_forumAudit')) OR EXISTS(SELECT 1 FROM jsonb_each(p_filter) kv WHERE jsonb_typeof(kv.value) NOT IN ('string','boolean')) THEN RAISE EXCEPTION 'INVALID_FORUM_FILTER'; END IF;
IF p_filter ? '_beforeFloor' AND (p_filter->>'_beforeFloor' !~ '^[0-9]{1,9}$' OR p_collection<>'forum_comments') THEN RAISE EXCEPTION 'INVALID_FLOOR'; END IF;
IF p_limit<1 OR p_limit>50 OR p_offset<0 THEN RAISE EXCEPTION 'INVALID_PAGE'; END IF;
IF p_filter ? '_sort' AND p_filter->>'_sort' NOT IN ('latest','reply','hot','oldest','featured') THEN RAISE EXCEPTION 'INVALID_SORT'; END IF;
CASE p_collection
WHEN 'forum_boards' THEN
EXECUTE 'WITH filtered AS (SELECT r.id,r.data FROM electronicclub.forum_boards r WHERE  (NOT $1::jsonb ? ''status'' OR r.data->>''status''=$1::jsonb->>''status'') AND (NOT $1::jsonb ? ''boardId'' OR r.data->>''boardId''=$1::jsonb->>''boardId'') AND (NOT $1::jsonb ? ''postId'' OR r.data->>''postId''=$1::jsonb->>''postId'') AND (NOT $1::jsonb ? ''authorUid'' OR r.data->>''authorUid''=$1::jsonb->>''authorUid'') AND (NOT $1::jsonb ? ''recipientUid'' OR r.data->>''recipientUid''=$1::jsonb->>''recipientUid'') AND (NOT $1::jsonb ? ''reporterUid'' OR r.data->>''reporterUid''=$1::jsonb->>''reporterUid'') AND (NOT $1::jsonb ? ''ownerUid'' OR r.data->>''ownerUid''=$1::jsonb->>''ownerUid'') AND (NOT $1::jsonb ? ''uid'' OR r.data->>''uid''=$1::jsonb->>''uid'') AND (NOT $1::jsonb ? ''read'' OR r.data->>''read''=$1::jsonb->>''read'') AND (NOT $1::jsonb ? ''_notDeleted'' OR r.data->>''status''<>''deleted'') AND (NOT $1::jsonb ? ''_public'' OR (r.data->>''status'' IN (''active'',''disabled''))) AND (NOT $1::jsonb ? ''_favoriteUid'' OR (false)) AND (NOT $1::jsonb ? ''_featured'' OR r.data->>''featured''=''true'') AND (NOT $1::jsonb ? ''_createdBefore'' OR (r.data->>''createdAt'')::timestamptz<($1::jsonb->>''_createdBefore'')::timestamptz) AND (NOT $1::jsonb ? ''_beforeFloor'' OR (r.data->>''floor'')::integer<($1::jsonb->>''_beforeFloor'')::integer) AND (NOT $1::jsonb ? ''_search'' OR strpos(lower(coalesce(r.data->>''title'','''')||'' ''||coalesce(r.data->>''body'','''')||'' ''||coalesce(r.data->>''name'','''')),lower($1::jsonb->>''_search''))>0)),paged AS (SELECT id,data,row_number() OVER(ORDER BY (data->>''position'')::integer,id) AS n FROM filtered ORDER BY (data->>''position'')::integer,id LIMIT $2 OFFSET $3) SELECT jsonb_build_object(''total'',(SELECT count(*) FROM filtered),''items'',coalesce((SELECT jsonb_agg(data||jsonb_build_object(''id'',id) ORDER BY n) FROM paged),''[]''::jsonb)) AS result' INTO result USING p_filter,p_limit,p_offset;
WHEN 'forum_posts' THEN
EXECUTE 'WITH filtered AS (SELECT r.id,r.data FROM electronicclub.forum_posts r WHERE  (NOT $1::jsonb ? ''status'' OR r.data->>''status''=$1::jsonb->>''status'') AND (NOT $1::jsonb ? ''boardId'' OR r.data->>''boardId''=$1::jsonb->>''boardId'') AND (NOT $1::jsonb ? ''postId'' OR r.data->>''postId''=$1::jsonb->>''postId'') AND (NOT $1::jsonb ? ''authorUid'' OR r.data->>''authorUid''=$1::jsonb->>''authorUid'') AND (NOT $1::jsonb ? ''recipientUid'' OR r.data->>''recipientUid''=$1::jsonb->>''recipientUid'') AND (NOT $1::jsonb ? ''reporterUid'' OR r.data->>''reporterUid''=$1::jsonb->>''reporterUid'') AND (NOT $1::jsonb ? ''ownerUid'' OR r.data->>''ownerUid''=$1::jsonb->>''ownerUid'') AND (NOT $1::jsonb ? ''uid'' OR r.data->>''uid''=$1::jsonb->>''uid'') AND (NOT $1::jsonb ? ''read'' OR r.data->>''read''=$1::jsonb->>''read'') AND (NOT $1::jsonb ? ''_notDeleted'' OR r.data->>''status''<>''deleted'') AND (NOT $1::jsonb ? ''_public'' OR (r.data->>''status''=''published'' AND EXISTS(SELECT 1 FROM electronicclub.forum_boards b WHERE b.id=r.data->>''boardId'' AND b.data->>''status'' IN (''active'',''disabled'')))) AND (NOT $1::jsonb ? ''_favoriteUid'' OR (EXISTS(SELECT 1 FROM electronicclub.forum_favorites f WHERE f.data->>''postId''=r.id AND f.data->>''uid''=$1::jsonb->>''_favoriteUid''))) AND (NOT $1::jsonb ? ''_featured'' OR r.data->>''featured''=''true'') AND (NOT $1::jsonb ? ''_createdBefore'' OR (r.data->>''createdAt'')::timestamptz<($1::jsonb->>''_createdBefore'')::timestamptz) AND (NOT $1::jsonb ? ''_beforeFloor'' OR (r.data->>''floor'')::integer<($1::jsonb->>''_beforeFloor'')::integer) AND (NOT $1::jsonb ? ''_search'' OR strpos(lower(coalesce(r.data->>''title'','''')||'' ''||coalesce(r.data->>''body'','''')||'' ''||coalesce(r.data->>''name'','''')),lower($1::jsonb->>''_search''))>0)),paged AS (SELECT id,data,row_number() OVER(ORDER BY coalesce((data->>''pinned'')::boolean,false) DESC,CASE WHEN $1::jsonb->>''_sort''=''hot'' THEN coalesce((data->>''likeCount'')::integer,0)*3+coalesce((data->>''commentCount'')::integer,0)*2 END DESC NULLS LAST,CASE WHEN $1::jsonb->>''_sort''=''reply'' THEN data->>''lastReplyAt'' ELSE data->>''createdAt'' END DESC,id) AS n FROM filtered ORDER BY coalesce((data->>''pinned'')::boolean,false) DESC,CASE WHEN $1::jsonb->>''_sort''=''hot'' THEN coalesce((data->>''likeCount'')::integer,0)*3+coalesce((data->>''commentCount'')::integer,0)*2 END DESC NULLS LAST,CASE WHEN $1::jsonb->>''_sort''=''reply'' THEN data->>''lastReplyAt'' ELSE data->>''createdAt'' END DESC,id LIMIT $2 OFFSET $3) SELECT jsonb_build_object(''total'',(SELECT count(*) FROM filtered),''items'',coalesce((SELECT jsonb_agg(data||jsonb_build_object(''id'',id) ORDER BY n) FROM paged),''[]''::jsonb)) AS result' INTO result USING p_filter,p_limit,p_offset;
